html:
{{ print_control(doc) }}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- set trainers = [] -%}
{%- for row in doc.get("custom_trainers") or [] -%}
{%- set _ = trainers.append(row.trainer_name or (frappe.db.get_value("Employee", row.employee, "employee_name")
  if row.employee else "")) -%}
{%- endfor -%}
{%- if not trainers and doc.trainer_name -%}{%- set _ = trainers.append(doc.trainer_name) -%}{%- endif -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11px; color: #000; line-height: 1.4; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 10px; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 3px 5px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form .ref td { font-size: 10px; }
.lpl-form .tall td { height: 22px; }
.lpl-form .tick { width: 9%; }
.lpl-form .line { border-bottom: 1px dotted #000; height: 20px; margin: 0 0 4px 18px; }
.lpl-form h4 { font-size: 11px; font-weight: bold; margin: 8px 0 4px; }
.lpl-page { page-break-after: always; }
.lpl-page:last-child { page-break-after: auto; }
</style>
<div class="lpl-form">
<table class="ref"><tr>
<td rowspan="2" style="width:40%"><b>LUUKA PLASTICS LIMITED</b></td>
<td>Doc Ref. No: LPL/TRG/FRM03</td><td>Initial Issue Date 24/04/2017</td></tr>
<tr><td>Revision Date: 01/10/2024</td><td>Revision No. 3</td></tr>
<tr><td colspan="3" style="text-align:center"><b>TRAINING ATTENDANCE FORM</b></td></tr></table>

{%- set first = frappe.utils.getdate(doc.start_time) if doc.start_time else none -%}
{%- set last = frappe.utils.getdate(doc.end_time) if doc.end_time else first -%}
{%- set days = ([[((last - first).days + 1) if first and last else 1, 1] | max, 5] | min) -%}
<table>
<tr><th style="width:18%">Training title</th><td>{{ v(doc.event_name or doc.training_program) }}</td></tr>
<tr><th>Training dates</th><td>{{ day(first) }}{% if last and last != first %} to {{ day(last) }}{% endif %}</td></tr>
<tr><th>Venue</th><td>{{ v(doc.location) }}</td></tr>
</table>
<table>
{%- for name in (trainers + ["", "", ""])[:([trainers | length, 3] | max)] %}
<tr><th style="width:12%">Trainer {{ loop.index }}:</th><td style="width:40%">{{ v(name) }}</td>
<th style="width:12%">Signature:</th><td></td><th style="width:8%">Date:</th><td style="width:12%"></td></tr>
{%- endfor %}
</table>
<table class="tall">
<tr><th rowspan="2" style="width:5%">S/N</th><th rowspan="2" style="width:24%">Trainee Name</th>
<th rowspan="2" style="width:20%">Department/Section</th><th rowspan="2">Email address</th>
<th colspan="{{ days }}" style="text-align:center">Signature</th></tr>
<tr>{% for n in range(days) %}<th style="width:9%">Day {{ n + 1 }}</th>{% endfor %}</tr>
{%- set people = doc.get("employees") or [] %}
{%- for row in people %}
{%- set mail = frappe.db.get_value("Employee", row.employee, "company_email")
  or frappe.db.get_value("Employee", row.employee, "personal_email") if row.employee else "" %}
{%- set section = frappe.db.get_value("Employee", row.employee, "custom_work_section") if row.employee else "" %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.employee_name) }}</td>
<td>{{ v(row.department) }}{% if section %} / {{ v(section) }}{% endif %}</td><td>{{ v(mail) }}</td>
{% for n in range(days) %}<td></td>{% endfor %}</tr>
{%- endfor %}
{%- for n in range([18 - (people | length), 0] | max) %}
<tr><td>{{ (people | length) + n + 1 }}</td><td></td><td></td><td></td>{% for d in range(days) %}<td></td>{% endfor %}</tr>
{%- endfor %}
</table>
</div>
